qrTask = { provider: provider.id, taskId: d.data.taskId, cookieField: provider.cookieField };
qrSetMsg(d.data.msg || '');
if (d.data.qrImage) renderQrImage(d.data.qrImage);
else renderQr(d.data.qrUrl);
