// \u7EDF\u4E00\u89C4\u8303\u5316\u64AD\u653E\u4F4D\u5740\uFF08\u517C\u5BB9\u672C\u5730\u4EE3\u7406\u3001\u7AEF\u53E3\u6620\u5C04\u3001\u8DE8\u57DF\u53CA\u5C40\u57DF\u7F51\u8BBF\u95EE\uFF09
function normalizePlayUrl(rawUrl) {
if (!rawUrl || typeof rawUrl !== 'string') return '';
const trimmed = rawUrl.trim();
if (trimmed.startsWith('/')) {
return window.location.origin + trimmed;
}
try {
const u = new URL(trimmed);
// \u5982\u679C\u662F\u672C\u670D\u52D9\u4EE3\u7406\u7AEF\u70B9\u6216\u672C\u5730\u7DB2\u57DF\u540D\u7A31\uFF0C\u81EA\u52A8\u4F7F\u7528\u7576\u524D\u8BBF\u95EE\u7684\u534F\u8BAE+\u7DB2\u57DF\u540D\u7A31+\u7AEF\u53E3
if (u.pathname.includes('/proxy/m3u8') || u.pathname.includes('/proxy/ts') || u.pathname.startsWith('/spider/')) {
return window.location.origin + u.pathname + u.search + u.hash;
}
if (['localhost', '127.0.0.1', '0.0.0.0'].includes(u.hostname)) {
return window.location.origin + u.pathname + u.search + u.hash;
}
return trimmed;
} catch (e) {
return trimmed;
}
}
// \u6E32\u67D3\u64AD\u653E\u7D50\u679C
