// \u5132\u5B58\u72C0\u614B\uFF08\u907F\u514D\u540C\u4E00\u5206\u985E\u7BE9\u9078\u6216\u7FFB\u9801\u6642\u91CD\u8907\u8FFD\u52A0\u9EB5\u5305\u5C51\uFF09
function saveState(level, data, breadcrumbName) {
const lastIdx = navHistory.length - 1;
const lastState = lastIdx >= 0 ? navHistory[lastIdx] : null;
// 1. \u5982\u679C\u5728\u540C\u4E00\u5206\u985E/\u76EE\u9304\uFF08\u540C level \u4E14\u540C categoryId\uFF09\uFF0C\u6216\u540C\u5F71\u7247\u8A73\u60C5\uFF0C\u50C5\u539F\u4F4D\u66F4\u65B0\u6578\u64DA\u8207\u7BE9\u9078\u53C3\u6578\uFF0C\u7D55\u4E0D\u91CD\u8907\u7D2F\u52A0\u9EB5\u5305\u5C51
if (lastState && lastState.level === level) {
if (level === 'category' && lastState.categoryId === currentState.categoryId) {
navHistory[lastIdx] = {
...currentState,
level,
data,
breadcrumbName
};
updateBreadcrumb(navHistory.map(s => s.breadcrumbName));
return;
}
if (level === 'detail' && lastState.videoId === currentState.videoId) {
navHistory[lastIdx] = {
...currentState,
level,
data,
breadcrumbName
};
updateBreadcrumb(navHistory.map(s => s.breadcrumbName));
return;
}
if (level === 'home') {
navHistory[lastIdx] = {
...currentState,
level,
data,
breadcrumbName
};
updateBreadcrumb(navHistory.map(s => s.breadcrumbName));
return;
}
}
// 2. \u6B63\u5E38\u65B0\u589E\u5C64\u7D1A\uFF08\u4F8B\u5982 Home -> Category\uFF0C\u6216 ParentFolder -> SubFolder\uFF0C\u6216 Category -> Detail\uFF09
navHistory.push({
...currentState,
level,
data,
breadcrumbName
});
updateBreadcrumb(navHistory.map(s => s.breadcrumbName));
}
// \u5C0E\u822A\u5230\u6B77\u53F2\u8A18\u9304
function navigateTo(index) {
if (index < 0 || index >= navHistory.length) return;
const state = navHistory[index];
navHistory = navHistory.slice(0, index + 1);
restoreState(state);
updateBreadcrumb(navHistory.map(s => s.breadcrumbName));
}
// \u6062\u590D\u72C0\u614B
function restoreState(state) {
currentState = { ...state };
switch (state.level) {
case 'home':
renderHome(state.data, true);
break;
case 'category':
renderCategory(state.data, true);
break;
case 'detail':
renderDetail(state.data, true);
break;
}
}
